part of 'academy_english_advanced_models.dart';
abstract final class EnglishAdvancedA2UnitTwoFirst {
  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:1,title:"A Room of Your Own",titleArabic:"غرفة خاصة بك",storyTitle:"A Room of Your Own",storyTitleArabic:"غرفة خاصة بك",paragraphs:<String>["Salma moved into a shared house and entered her empty bedroom. She opened the curtains and measured the space near the wardrobe. She wanted a peaceful place to read without spending too much money.","At a furniture market, she found a second-hand desk, a lamp and a rug. Her roommate helped carry the furniture upstairs and place a mirror on the wall. They laughed when the rug was too wide.","That evening, Salma arranged her books on a shelf and put photographs near the window. The room looked brighter and felt comfortable. She thanked her roommate for the help and invited a friend to visit."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bedroom","غرفة نوم"),EnglishAdvancedWord("curtains","ستائر"),EnglishAdvancedWord("measured","قاس"),EnglishAdvancedWord("wardrobe","خزانة ملابس"),EnglishAdvancedWord("peaceful","هادئ"),EnglishAdvancedWord("furniture","أثاث"),EnglishAdvancedWord("second-hand","مستعمل"),EnglishAdvancedWord("desk","مكتب"),EnglishAdvancedWord("lamp","مصباح"),EnglishAdvancedWord("rug","سجادة صغيرة"),EnglishAdvancedWord("roommate","شريك سكن"),EnglishAdvancedWord("mirror","مرآة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("pillowcase","غطاء وسادة"),EnglishAdvancedWord("bedsheet","ملاءة سرير"),EnglishAdvancedWord("nightstand","طاولة جانبية"),EnglishAdvancedWord("extension cord","وصلة كهربائية"),EnglishAdvancedWord("storage box","صندوق تخزين"),EnglishAdvancedWord("coat hanger","علاقة معطف"),EnglishAdvancedWord("laundry basket","سلة غسيل"),EnglishAdvancedWord("window ledge","حافة نافذة"),EnglishAdvancedWord("floor plan","مخطط غرفة"),EnglishAdvancedWord("wall hook","خطاف حائط"),EnglishAdvancedWord("reading corner","ركن قراءة"),EnglishAdvancedWord("soft lighting","إضاءة ناعمة")],grammarTitle:"Comparatives and enough",grammarArabic:"للمقارنة نستخدم brighter than أو more comfortable than. نضع enough بعد الصفة: big enough؛ وقبل الاسم: enough space.",grammarExamples:<String>["This room is brighter than the old one.","This desk is small enough to fit here.","I do not have enough space for a sofa."],listening:"Hello, Salma. Your desk and lamp are ready for delivery on Tuesday between ten and twelve. The wall shelf is delayed until Thursday. Please arrange for someone to sign for the furniture. The driver can carry the desk upstairs, but if you live above the first floor, he may need some help. Call us today if you need a different delivery time.",listeningQuestion:"Which item is delayed? ",listeningOptions:<String>["The wall shelf","The desk","The lamp"],listeningAnswer:0,readingQuestion:"How did Salma make the room comfortable?",readingOptions:<String>["With simple furniture and books","By buying a car","By replacing the windows"],readingAnswer:0,writingCue:"Salma opened the ____.",writingAnswer:"curtains"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:2,title:"The Doctor's Advice",titleArabic:"نصيحة الطبيب",storyTitle:"The Doctor's Advice",storyTitleArabic:"نصيحة الطبيب",paragraphs:<String>["After two nights of poor sleep, Omar visited a clinic. He felt dizzy and had a sore throat. The nurse checked his temperature and told him to wait in a quiet room.","The doctor examined Omar and found a mild infection. She gave him medicine and clear instructions. Omar had to drink water, get enough rest and watch for a high fever.","Back at home, Omar made warm tea and called his sister. He stored the clinic's phone number in case he needed more advice. After sleeping well, he felt better the next morning."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("clinic","عيادة"),EnglishAdvancedWord("poor sleep","قلة نوم"),EnglishAdvancedWord("dizzy","دوار"),EnglishAdvancedWord("quiet room","غرفة هادئة"),EnglishAdvancedWord("nurse","ممرضة"),EnglishAdvancedWord("temperature","حرارة"),EnglishAdvancedWord("examined","فحص"),EnglishAdvancedWord("infection","عدوى"),EnglishAdvancedWord("medicine","دواء"),EnglishAdvancedWord("instructions","تعليمات"),EnglishAdvancedWord("fever","حمى"),EnglishAdvancedWord("warm tea","شاي دافئ")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("prescription","وصفة طبية"),EnglishAdvancedWord("appointment slot","موعد متاح"),EnglishAdvancedWord("follow-up call","اتصال متابعة"),EnglishAdvancedWord("blood pressure","ضغط دم"),EnglishAdvancedWord("allergy test","اختبار حساسية"),EnglishAdvancedWord("pulse check","فحص النبض"),EnglishAdvancedWord("oral rehydration","تعويض السوائل"),EnglishAdvancedWord("side effect","أثر جانبي"),EnglishAdvancedWord("recovery time","فترة تعافٍ"),EnglishAdvancedWord("medical history","تاريخ طبي"),EnglishAdvancedWord("walk-in service","خدمة بلا موعد"),EnglishAdvancedWord("urgent consultation","استشارة عاجلة")],grammarTitle:"Should, shouldn't and must",grammarArabic:"نعطي نصيحة بـ should + فعل، وshouldn't للتجنب، وmust للتعبير عن ضرورة قوية. لا نضع to بعد هذه الأفعال المساعدة.",grammarExamples:<String>["You should get some rest.","You shouldn't ignore a high fever.","You must follow the instructions."],listening:"This is a message from the local clinic. Please arrive ten minutes before your appointment and bring a list of your current medicines. The doctor may ask about allergies and recent symptoms. If you cannot attend, call before nine in the morning. For serious breathing problems, do not wait for an ordinary appointment; seek urgent help.",listeningQuestion:"What should patients bring?",listeningOptions:<String>["A medicine list","A train ticket","A shopping receipt"],listeningAnswer:0,readingQuestion:"Why did Omar visit a doctor?",readingOptions:<String>["He felt dizzy and unwell","He needed a bicycle","He wanted a new job"],readingAnswer:0,writingCue:"Omar went to the ____.",writingAnswer:"clinic"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:3,title:"A Recipe from Home",titleArabic:"وصفة من البيت",storyTitle:"A Recipe from Home",storyTitleArabic:"وصفة من البيت",paragraphs:<String>["Mira invited her new neighbors to dinner and planned to cook a family dish. She asked her grandmother for advice, bought herbs and vegetables, and washed the ingredients carefully.","She heated a pan with oil and stirred some onions. Then she added broth and let everything cook slowly. She tasted the food before adding salt because she wanted the flavor to be just right.","When the guests arrived, Mira served the meal in a large bowl. Her neighbors enjoyed the delicious smell and asked how to make it. Mira explained the steps, happy to share her family traditions."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("neighbors","جيران"),EnglishAdvancedWord("family dish","طبق عائلي"),EnglishAdvancedWord("grandmother","جدة"),EnglishAdvancedWord("herbs","أعشاب"),EnglishAdvancedWord("delicious smell","رائحة شهية"),EnglishAdvancedWord("pan","مقلاة"),EnglishAdvancedWord("stirred","حرّك"),EnglishAdvancedWord("onions","بصل"),EnglishAdvancedWord("broth","مرق"),EnglishAdvancedWord("tasted","تذوق"),EnglishAdvancedWord("salt","ملح"),EnglishAdvancedWord("bowl","وعاء")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("flour sieve","منخل طحين"),EnglishAdvancedWord("wooden spoon","ملعقة خشبية"),EnglishAdvancedWord("simmer","يطهو بهدوء"),EnglishAdvancedWord("seasoning","بهارات"),EnglishAdvancedWord("chopping board","لوح تقطيع"),EnglishAdvancedWord("glass jar","مرطبان زجاجي"),EnglishAdvancedWord("pot lid","غطاء قدر"),EnglishAdvancedWord("serving spoon","ملعقة تقديم"),EnglishAdvancedWord("leftovers","بقايا الطعام"),EnglishAdvancedWord("heat setting","درجة الموقد"),EnglishAdvancedWord("oven mitt","قفاز فرن"),EnglishAdvancedWord("food container","علبة طعام")],grammarTitle:"First, then and finally",grammarArabic:"للإرشادات نستخدم First ثم Then ثم Finally، وبعدها فعل أمر مجرد مثل chop وpour وserve، لتوضيح ترتيب الخطوات.",grammarExamples:<String>["First, chop the onions.","Then, pour in the broth.","Finally, serve the meal."],listening:"Welcome to our home cooking class. First, chop the vegetables and prepare all your equipment before turning on the stove. Then heat the pan, add a little oil and stir for five minutes. Next, pour in the broth and reduce the heat. Finally, taste the food carefully before adding salt. Good seasoning takes practice, so do not rush.",listeningQuestion:"When should students add salt?",listeningOptions:<String>["After tasting","Before washing the vegetables","Before heating the pan"],listeningAnswer:0,readingQuestion:"Why was Mira happy at dinner?",readingOptions:<String>["She shared her family traditions","She ordered food","She bought a bicycle"],readingAnswer:0,writingCue:"Mira added ____ to the pan.",writingAnswer:"broth")
  ];
}
